      'La Declaración de Glasgow pide cinco cosas a quien hospeda: medir, descarbonizar, regenerar, colaborar y financiar. Contesta lo que sepas hoy; lo que no, déjalo. Vale más un «no» honesto que un «sí» de adorno — esto lo acaba viendo un huésped.':'The Glasgow Declaration asks five things of anyone who hosts: measure, decarbonise, regenerate, collaborate and finance. Answer what you know today; leave the rest. An honest “no” is worth more than a decorative “yes” — a guest ends up reading this.',
