      'No estás apartando la sala: estás diciendo cuándo está disponible.':'You are not holding the room: you are saying when it is available.',
      'No había ninguna foto nueva que traer':'There was no new photo to fetch',
      'No había pagado nada, así que no hay cargo que devolver.':'They had paid nothing, so there is no charge to refund.',
      'No hace falta estar hospedado para entrar — quien llega de fuera puede comprar igual.':'You do not have to be staying here to come in — anyone from outside can buy just the same.',
      'No hay discusión que perder, pero sí hay que calcularlo: una comisión variable mueve el salario integrado mes a mes, y tu contador tiene que estar enterado desde el primero.':'There is no argument to lose, but it does have to be worked out: a variable commission moves the integrated salary month by month, and your accountant has to know from day one.',
      'No hay función: alguien viene a usar la sala. Grabar, ensayar, una sesión. La misma intermediación sobre lo que cobres.':'There is no show: someone comes to use the room. Recording, rehearsing, a session. The same brokerage on whatever you charge.',
