      'Cuatro bandas de la ciudad, una noche. Ariel Eléctrico no es un festival ni un homenaje: es la noche en que la Sala Mayor se queda sin sillas. Abren a las nueve y cierran cuando el Ateneo apaga las luces. Barra abierta de cerveza del Cumbre hasta la medianoche.':'Four bands from the city, one night. Ariel Eléctrico is neither a festival nor a tribute: it is the night the Sala Mayor runs out of chairs. Doors at nine, and it ends when the Ateneo turns the lights off. Open bar of Cumbre beer until midnight.',
      'Cuatro horas en el patio, con engrudo hasta los codos. Se arma la estructura con alambre y carrizo, se forra con papel de estraza y se pinta. Cada quien se lleva su bestia a casa. Lo da Citlali Herrán, cartonera de tercera generación. El material va incluido; la ropa que te importe, déjala en casa.':'Four hours in the courtyard, up to your elbows in paste. You build the frame from wire and reed, cover it in brown paper and paint it. Everyone takes their beast home. Citlali Herrán runs it, a third-generation papier-mâché maker. Materials are included; leave any clothes you care about at home.',
      'Cuatro miércoles para escribir un ensayo y defenderlo en voz alta. Se lee a Reyes, a Torri y a quien cada quien traiga; se escribe en el aula y se corrige entre todos. No hace falta haber publicado nada: hace falta tener algo que discutir. Dieciocho lugares, ni uno más.':'Four Wednesdays to write an essay and defend it out loud. We read Reyes, Torri and whoever each person brings along; you write in the room and everyone edits together. You do not need to have published anything: you need something to argue about. Eighteen places, not one more.',
      'Dirección escénica':'Stage direction',
      'Dirige las lecturas escenificadas. Doce años montando teatro de texto en patios y azoteas del Centro.':'Directs the staged readings. Twelve years putting on text-based theatre in courtyards and rooftops downtown.',
      'Dos de los dieciocho lugares son becados, para estudiantes de preparatoria pública del Centro.':'Two of the eighteen places are scholarships, for students at public secondary schools downtown.',
      'Dos días sobre lo que la tecnología le está haciendo al oficio de recibir: reservas, datos, precios y el trato con el huésped. Mesas por la mañana y talleres por la tarde, con gente de hotelería, de plataformas y de las comunidades que reciben. Incluye comida los dos días y el acceso a las grabaciones.':'Two days on what technology is doing to the craft of hosting: bookings, data, prices and how you treat a guest. Panels in the morning and workshops in the afternoon, with people from hospitality, from the platforms and from the communities who do the hosting. Lunch both days and access to the recordings are included.',
      'El Banquete':'The Symposium',
