      'Las cuatro bandas son de la Ciudad de México y cobran taquilla, no exposición.':'All four bands are from Mexico City and are paid from the box office, not in exposure.',
      'Lectura escenificada':'Staged reading',
      'Llevamos cuatro años programando en el Centro Histórico. Desde 2026 lo hacemos en Izazaga 8, en las salas del Ateneo de Virreyes.':'We have been programming in the Centro Histórico for four years. Since 2026 we do it at Izazaga 8, in the rooms of the Ateneo de Virreyes.',
      'Los retratos son fotos de archivo: quienes aparecen no tienen relación con esta página':'The portraits are stock photos: the people in them have no connection to this page',
      'Montaje, audio y el minuto a minuto de cada función.':'Set-up, sound and the minute-by-minute of every show.',
      'No somos aquello, y no lo pretendemos. Lo que copiamos es el método: que la conferencia y el concierto quepan en el mismo programa, que el taller valga tanto como la función, y que entrar no dependa de a quién conozcas.':'We are not that, and we do not claim to be. What we copy is the method: that the lecture and the concert fit in the same programme, that the workshop counts as much as the show, and that getting in does not depend on who you know.',
      'Noche de décimas':'Décimas night',
      'Nuestro alebrije, en el desfile de Reforma.':'Our alebrije, in the Reforma parade.',
      'Producción':'Production',
      'Programamos el Ateneo de Virreyes como se programaba el de 1909: concierto, taller y lectura en el mismo patio, y la puerta abierta a quien llegue.':'We programme the Ateneo de Virreyes the way the 1909 one was programmed: a concert, a workshop and a reading in the same courtyard, and the door open to whoever turns up.',
      'Seis personas a la mesa, seis discursos sobre el amor. El diálogo de Platón leído en escena, sin vestuario y sin cuarta pared, en la traducción que se trabajó en el taller del Ateneo. Dura hora y cuarenta sin intermedio. Al final hay vino y se sigue discutiendo, que de eso iba.':'Six people at the table, six speeches about love. Plato\'s dialogue read on stage, with no costumes and no fourth wall, in the translation worked on in the Ateneo\'s workshop. It runs one hour forty, no interval. There is wine at the end and the arguing carries on, which was rather the point.',
      'Su web':'Their website',
      'Taller de alebrijes':'Alebrije workshop',
      'Taller · 4 sesiones':'Workshop · 4 sessions',
      'Tomamos el nombre del Ateneo de la Juventud, la sociedad que un grupo de jóvenes fundó en la Ciudad de México en 1909: Antonio Caso, Pedro Henríquez Ureña, José Vasconcelos, Alfonso Reyes, Julio Torri, Martín Luis Guzmán. Discutían contra el positivismo que entonces mandaba en la enseñanza, leían a los griegos en voz alta y daban conferencias públicas a las que podía entrar cualquiera. Años después, Vasconcelos fundaría la Secretaría de Educación Pública y abriría las paredes del país a los muralistas y las vitrinas a los artesanos.':'We take our name from the Ateneo de la Juventud, the society a group of young people founded in Mexico City in 1909: Antonio Caso, Pedro Henríquez Ureña, José Vasconcelos, Alfonso Reyes, Julio Torri, Martín Luis Guzmán. They argued against the positivism that ruled teaching at the time, read the Greeks aloud and gave public lectures anyone could walk into. Years later, Vasconcelos would found the Ministry of Public Education and open the country\'s walls to the muralists and its display cases to the artisans.',
